// Owner-approved standalone NeuralSynch wave, bundled without external resources.
export const WORKFLOW_LOGO="data:image/png;base64,";
export const WORKFLOW_CSS=".ns-workflow{display:flex;align-items:center;gap:20px;padding:20px!important;margin:14px 0;border:1px solid #3863a2!important;border-radius:18px;background:radial-gradient(ellipse at top left,#122e52 0,transparent 48%),linear-gradient(120deg,#091627,#07101e);box-shadow:inset 0 0 24px #156fe418,0 4px 18px #03122524;color:#eef7ff;font:14px/1.45 system-ui,sans-serif;max-width:100%;box-sizing:border-box}\n.ns-workflow[hidden]{display:none!important}\n.ns-workflow-wave{flex:0 0 72px;padding-right:16px;border-right:1px solid #314763;filter:drop-shadow(0 0 8px #25e8fa66)}\n.ns-workflow[data-state=running] .ns-workflow-wave{animation:ns-wave-breathe 2.4s ease-in-out infinite}\n.ns-workflow-body{min-width:0;flex:1}.ns-workflow-header{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:6px 16px}.ns-workflow-header strong{font-size:18px;color:#f5faff}.ns-workflow-header small{font-size:11px;color:#a9c6df;max-width:290px}.ns-workflow .ns-workflow-status{margin:5px 0 18px;color:#b9d4ea;font-size:14px}\n.ns-workflow-milestones{display:grid!important;grid-template-columns:repeat(var(--ns-workflow-count,6),minmax(0,1fr));list-style:none!important;padding:0!important;margin:0!important;gap:0}\n.ns-workflow-milestones li{position:relative;display:flex;flex-direction:column;align-items:center;text-align:center;gap:7px;font-size:11px;color:#9ab1ca;min-width:0;padding:0!important;overflow-wrap:anywhere}\n.ns-workflow-milestones li:before{content:\"\";position:absolute;top:11px;left:-50%;width:100%;height:2px;background:#31445e}.ns-workflow-milestones li:first-child:before{display:none}.ns-workflow-milestones li[data-state=complete]:before,.ns-workflow-milestones li[data-state=active]:before{background:#35dce9}\n.ns-workflow-node{position:relative;z-index:1;display:grid;place-items:center;width:24px;height:24px;box-sizing:border-box;border:2px solid #526c8c;border-radius:50%;background:#102036;font-size:16px;font-weight:800}\n.ns-workflow-milestones li[data-state=complete]{color:#9af1f9}.ns-workflow-milestones li[data-state=complete] .ns-workflow-node{border-color:#69f4fa;background:#69f4fa;color:#07334b}.ns-workflow-milestones li[data-state=active]{color:white}.ns-workflow-milestones li[data-state=active] .ns-workflow-node{border-color:#56efff;box-shadow:0 0 12px #198bff;background:#247dd8;animation:ns-node-breathe 2s ease-in-out infinite}\n.ns-workflow-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}\n@keyframes ns-wave-breathe{50%{filter:drop-shadow(0 0 14px #40eaffaa);transform:translateY(-2px)}}@keyframes ns-node-breathe{50%{box-shadow:0 0 16px #24dfff}}\n@media(max-width:600px){.ns-workflow{gap:12px;padding:14px!important;align-items:flex-start}.ns-workflow-wave{flex-basis:36px;padding-right:8px;margin-top:4px}.ns-workflow-wave img{max-width:36px;height:auto!important}.ns-workflow-header strong{font-size:16px}.ns-workflow-milestones{grid-template-columns:repeat(3,minmax(0,1fr));row-gap:14px}.ns-workflow-milestones li:nth-child(4):before{display:none}.ns-workflow-header small{max-width:none}}\n@media(prefers-reduced-motion:reduce){.ns-workflow *{animation:none!important;transition:none!important;transform:none!important}}\n";
